BEGIN;
CREATE TABLE IF NOT EXISTS tenant.crm_ai_model_registry(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,purpose text NOT NULL,provider text NOT NULL,model text NOT NULL,mode text NOT NULL DEFAULT 'rules' CHECK(mode IN('rules','external','hybrid')),configuration jsonb NOT NULL DEFAULT '{}'::jsonb,status text NOT NULL DEFAULT 'active' CHECK(status IN('draft','active','inactive')),version integer NOT NULL DEFAULT 1,created_by uuid REFERENCES public.users(id) ON DELETE SET NULL,updated_by uuid REFERENCES public.users(id) ON DELETE SET NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(organization_id,purpose,version));
CREATE TABLE IF NOT EXISTS tenant.crm_ai_recommendations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,entity_type text NOT NULL,entity_id uuid,recommendation_type text NOT NULL,title text NOT NULL,score numeric(5,2) NOT NULL CHECK(score BETWEEN 0 AND 100),reasoning jsonb NOT NULL DEFAULT '[]'::jsonb,payload jsonb NOT NULL DEFAULT '{}'::jsonb,model_version text NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN('pending','accepted','dismissed','completed','expired')),content_hash text NOT NULL,created_by uuid REFERENCES public.users(id) ON DELETE SET NULL,created_at timestamptz NOT NULL DEFAULT now(),acted_at timestamptz);
CREATE TABLE IF NOT EXISTS tenant.crm_relationship_intelligence_snapshots(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,entity_type text NOT NULL,entity_id uuid,score numeric(5,2) NOT NULL CHECK(score BETWEEN 0 AND 100),grade text NOT NULL,signals jsonb NOT NULL,model_version text NOT NULL,content_hash text NOT NULL,captured_by uuid REFERENCES public.users(id) ON DELETE SET NULL,captured_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS tenant.crm_ai_assistant_drafts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,entity_type text NOT NULL,entity_id uuid,purpose text NOT NULL,subject text,body text NOT NULL,grounding jsonb NOT NULL,provider text NOT NULL,model text NOT NULL,status text NOT NULL DEFAULT 'review_required' CHECK(status IN('review_required','approved','edited','discarded','sent')),content_hash text NOT NULL,created_by uuid REFERENCES public.users(id) ON DELETE SET NULL,updated_by uuid REFERENCES public.users(id) ON DELETE SET NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS tenant.crm_ai_deal_risk_snapshots(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,opportunity_id uuid,risk_score numeric(5,2) NOT NULL CHECK(risk_score BETWEEN 0 AND 100),risk_band text NOT NULL CHECK(risk_band IN('low','medium','high','critical')),reasons jsonb NOT NULL,model_version text NOT NULL,input_hash text NOT NULL,captured_by uuid REFERENCES public.users(id) ON DELETE SET NULL,captured_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS tenant.crm_ai_feedback(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,recommendation_id uuid,draft_id uuid,outcome text NOT NULL CHECK(outcome IN('accepted','dismissed','edited','successful','unsuccessful')),reason text,correction jsonb NOT NULL DEFAULT '{}'::jsonb,learnable boolean NOT NULL DEFAULT false,created_by uuid REFERENCES public.users(id) ON DELETE SET NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS tenant.crm_ai_acceptance_evidence(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,capability_id text NOT NULL,commit_sha text NOT NULL,status text NOT NULL CHECK(status IN('passed','failed','blocked')),evidence jsonb NOT NULL DEFAULT '{}'::jsonb,evidence_hash text NOT NULL,verified_by uuid REFERENCES public.users(id) ON DELETE SET NULL,verified_at timestamptz NOT NULL DEFAULT now(),UNIQUE(organization_id,capability_id,commit_sha));
CREATE INDEX IF NOT EXISTS crm_ai_recommendation_status_idx ON tenant.crm_ai_recommendations(organization_id,status,score DESC,created_at DESC);CREATE INDEX IF NOT EXISTS crm_ai_risk_latest_idx ON tenant.crm_ai_deal_risk_snapshots(organization_id,risk_band,captured_at DESC);
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['crm_ai_model_registry','crm_ai_recommendations','crm_relationship_intelligence_snapshots','crm_ai_assistant_drafts','crm_ai_deal_risk_snapshots','crm_ai_feedback','crm_ai_acceptance_evidence'] LOOP EXECUTE format('ALTER TABLE tenant.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE tenant.%I FORCE ROW LEVEL SECURITY',t);EXECUTE format('DROP POLICY IF EXISTS tenant_organization_isolation ON tenant.%I',t);EXECUTE format('CREATE POLICY tenant_organization_isolation ON tenant.%I USING (organization_id=current_setting(''app.current_organization_id'',true)::uuid) WITH CHECK (organization_id=current_setting(''app.current_organization_id'',true)::uuid)',t);END LOOP;END $$;
CREATE OR REPLACE FUNCTION tenant.crm_ai_evidence_immutable()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN RAISE EXCEPTION 'CRM AI evidence is immutable';END$$;DROP TRIGGER IF EXISTS crm_ai_acceptance_immutable ON tenant.crm_ai_acceptance_evidence;CREATE TRIGGER crm_ai_acceptance_immutable BEFORE UPDATE OR DELETE ON tenant.crm_ai_acceptance_evidence FOR EACH ROW EXECUTE FUNCTION tenant.crm_ai_evidence_immutable();GRANT SELECT,INSERT,UPDATE,DELETE ON ALL TABLES IN SCHEMA tenant TO vercent_app;COMMIT;
